import { Decimal } from '../shared/decimal.ts';

/**
 * Número de cuenta PIC 9(5): entero sin signo de 5 dígitos.
 */
export class AccountNumber {
  readonly value: Decimal;

  private constructor(value: Decimal) {
    this.value = value;
  }

  /**
   * Crea la cuenta truncando a 5 dígitos enteros y sin decimales.
   * @rule R-001
   */
  static fromDecimal(raw: Decimal): AccountNumber {
    return new AccountNumber(raw.setScale(0, 'DOWN').truncateToPic(5, 0));
  }

  /**
   * Formato fijo de 5 caracteres con ceros a la izquierda.
   * @rule R-001
   */
  format(): string {
    return this.value.toString().padStart(5, '0');
  }
}

import { Decimal } from '../shared/decimal.ts';

/**
 * Importe PIC 9999.99: 4 enteros y 2 decimales.
 */
export class TransactionAmount {
  readonly value: Decimal;

  private constructor(value: Decimal) {
    this.value = value;
  }

  /**
   * Aplica scale 2 sin ROUNDED (truncamiento) y limita a 4 enteros.
   * @rule R-002
   */
  static fromDecimal(raw: Decimal): TransactionAmount {
    return new TransactionAmount(raw.setScale(2, 'DOWN').truncateToPic(4, 2));
  }

  /**
   * Formato 9999.99 de 7 caracteres con ceros a la izquierda.
   * @rule R-002
   */
  format(): string {
    return this.value.toString().padStart(7, '0');
  }
}

import type { AccountNumber } from './AccountNumber.ts';
import type { TransactionAmount } from './TransactionAmount.ts';

/**
 * Transacción capturada. No se aplica ninguna validación de negocio.
 * @rule R-004
 */
export class Transaction {
  readonly fromAccount: AccountNumber;
  readonly toAccount: AccountNumber;
  readonly amount: TransactionAmount;

  constructor(fromAccount: AccountNumber, toAccount: AccountNumber, amount: TransactionAmount) {
    this.fromAccount = fromAccount;
    this.toAccount = toAccount;
    this.amount = amount;
  }
}

import type { Transaction } from './Transaction.ts';

/**
 * Registro de 17 caracteres: origen(5) + destino(5) + importe(7).
 */
export class TransactionRecord {
  readonly line: string;

  private constructor(line: string) {
    this.line = line;
  }

  /**
   * Compone el registro sin separadores y en orden fijo.
   * @rule R-003
   */
  static fromTransaction(transaction: Transaction): TransactionRecord {
    const line =
      transaction.fromAccount.format() +
      transaction.toAccount.format() +
      transaction.amount.format();
    return new TransactionRecord(line);
  }
}

/**
 * Política de fin de captura (ShouldContinue / Done).
 */
export class ContinuationPolicy {
  static readonly INITIAL_COMMAND = 'C';

  /**
   * Done es verdadero solo con Q o q.
   * @rule R-005
   */
  static isDone(command: string): boolean {
    return command === 'Q' || command === 'q';
  }

  /**
   * Se captura mientras Done sea falso (PERFORM UNTIL: se evalúa antes de cada iteración).
   * @rule R-005
   */
  static shouldCapture(command: string): boolean {
    return !ContinuationPolicy.isDone(command);
  }
}

import { Decimal } from '../shared/decimal.ts';

/**
 * Contador PIC 999999 de registros leídos.
 */
export class RecordCounter {
  readonly value: Decimal;

  private constructor(value: Decimal) {
    this.value = value;
  }

  /**
   * Counter empieza en 0.
   * @rule R-006
   */
  static start(): RecordCounter {
    return new RecordCounter(Decimal.of(0));
  }

  /**
   * ADD 1 sin ON SIZE ERROR: se trunca a 6 dígitos, sin control de desbordamiento.
   * @rule R-006
   */
  increment(): RecordCounter {
    return new RecordCounter(this.value.plus(Decimal.of(1)).truncateToPic(6, 0));
  }
}

import type { TransactionRecord } from '../../domain/transaction/TransactionRecord.ts';

/** Puerto de salida: añade registros al final de transactions.dat. */
export interface TransactionFileWriterPort {
  append(record: TransactionRecord): void;
}

/** Puerto de salida: lectura secuencial de transactions.dat. */
export interface TransactionFileReaderPort {
  readAll(): readonly string[];
}

import type { Decimal } from '../domain/shared/decimal.ts';
import { AccountNumber } from '../domain/transaction/AccountNumber.ts';
import { TransactionAmount } from '../domain/transaction/TransactionAmount.ts';
import { Transaction } from '../domain/transaction/Transaction.ts';
import { TransactionRecord } from '../domain/transaction/TransactionRecord.ts';
import type { TransactionFileWriterPort } from './ports/TransactionFileWriterPort.ts';

export interface RecordTransactionCommand {
  readonly fromAccount: Decimal;
  readonly toAccount: Decimal;
  readonly amount: Decimal;
}

export interface SaveTransactionResult {
  readonly transactionRecord: string;
  readonly status: 'OK';
}

/**
 * Construye y guarda una transacción sin validaciones de negocio.
 */
export class RecordTransactionUseCase {
  private readonly writer: TransactionFileWriterPort;

  constructor(writer: TransactionFileWriterPort) {
    this.writer = writer;
  }

  /**
   * @rule R-001
   * @rule R-002
   * @rule R-003
   * @rule R-004
   */
  execute(command: RecordTransactionCommand): SaveTransactionResult {
    const transaction = new Transaction(
      AccountNumber.fromDecimal(command.fromAccount),
      AccountNumber.fromDecimal(command.toAccount),
      TransactionAmount.fromDecimal(command.amount),
    );
    const record = TransactionRecord.fromTransaction(transaction);
    this.writer.append(record);
    return { transactionRecord: record.line, status: 'OK' };
  }
}

import { RecordCounter } from '../domain/reading/RecordCounter.ts';
import type { TransactionFileReaderPort } from './ports/TransactionFileReaderPort.ts';

/**
 * Cuenta los registros leídos del archivo de transacciones.
 */
export class CountTransactionsUseCase {
  private readonly reader: TransactionFileReaderPort;

  constructor(reader: TransactionFileReaderPort) {
    this.reader = reader;
  }

  /**
   * @rule R-006
   */
  execute(): string {
    let counter = RecordCounter.start();
    for (const _line of this.reader.readAll()) {
      counter = counter.increment();
    }
    return counter.value.toString();
  }
}

import type { TransactionRecord } from '../domain/transaction/TransactionRecord.ts';
import type { TransactionFileWriterPort } from '../application/ports/TransactionFileWriterPort.ts';
import type { TransactionFileReaderPort } from '../application/ports/TransactionFileReaderPort.ts';

/**
 * Archivo transactions.dat simulado en memoria (solo añade registros).
 */
export class InMemoryTransactionFile implements TransactionFileWriterPort, TransactionFileReaderPort {
  private readonly lines: string[];

  constructor() {
    this.lines = [];
  }

  append(record: TransactionRecord): void {
    this.lines.push(record.line);
  }

  readAll(): readonly string[] {
    return [...this.lines];
  }
}

import { Decimal } from '../domain/shared/decimal.ts';
import type { RecordTransactionCommand } from '../application/RecordTransactionUseCase.ts';

/**
 * Adaptador de entrada: convierte cadenas del contrato de E/S en tipos de dominio.
 */
export class StringInputMapper {
  toCommand(input: Record<string, string>): RecordTransactionCommand {
    return {
      fromAccount: StringInputMapper.toDecimal(input['from_account']),
      toAccount: StringInputMapper.toDecimal(input['to_account']),
      amount: StringInputMapper.toDecimal(input['amount']),
    };
  }

  private static toDecimal(raw: string | undefined): Decimal {
    const text = (raw ?? '0').trim();
    if (text === '') {
      return Decimal.of('0');
    }
    return Decimal.of(text.replace(/^0+(?=\d)/, ''));
  }
}

import { RecordTransactionUseCase } from './application/RecordTransactionUseCase.ts';
import { InMemoryTransactionFile } from './infrastructure/InMemoryTransactionFile.ts';
import { StringInputMapper } from './infrastructure/StringInputMapper.ts';

/**
 * Punto de entrada: compone dependencias y delega al caso de uso.
 */
export function execute(input: Record<string, string>): Record<string, string> {
  const file = new InMemoryTransactionFile();
  const useCase = new RecordTransactionUseCase(file);
  const command = new StringInputMapper().toCommand(input);
  const result = useCase.execute(command);
  return { transaction_record: result.transactionRecord, status: result.status };
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execute } from '../src/index.ts';

test('compone el registro de 17 caracteres', () => {
  const out = execute({ from_account: '123', to_account: '45678', amount: '125.50' });
  assert.equal(out['transaction_record'], '00123456780125.50');
  assert.equal(out['status'], 'OK');
});

test('trunca los decimales sobrantes del importe', () => {
  const out = execute({ from_account: '1', to_account: '2', amount: '10.129' });
  assert.equal(out['transaction_record'], '00001000020010.12');
});
